head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf32205";
scwin.pathname = undefined;
scwin.qry = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_O_INITDATE", fn: function(){ return (!(String(((dma_Cal14.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal14.O_INITDATE"); })())) == null ? '' : ((dma_Cal14.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal14.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_101", fn: function(){ return (!(String(((dma_Cal14.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal14.O_INITDATE"); })())) == null ? '' : ((dma_Cal14.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal14.O_INITDATE"); })()))).length === 0)); } }, { id: "if_O_INITDATE_2", fn: function(){ return (!(String(((dma_Cal15.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal15.O_INITDATE"); })())) == null ? '' : ((dma_Cal15.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal15.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_195", fn: function(){ return (!(String(((dma_Cal15.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal15.O_INITDATE"); })())) == null ? '' : ((dma_Cal15.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal15.O_INITDATE"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "ㆍ기산일(이사회결의 전일) : " + String(dma_Cal14.get("O_INITDATE")); } },
        { childId: "__rb1", fn: function () { return "ㆍ기산일(이사회결의 전일) : " + String(dma_Cal15.get("O_INITDATE")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", COM_NM);
};

// [A] 초기 목록 미해결 — jldstf32205: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_frmISU_CD = { action: "", method: 'post', target: '' };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf32205' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf32205' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf32205.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_63_onclick
 * @description img_63 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_63_onclick = function(e){
    try {
        IsurcdSearch2('ISU_CD','COM_NM',315,155)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf32205.img_63_onclick' }); }
};

/**
 * @method
 * @name img_63_onmouseover
 * @description img_63 onmouseover 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_63_onmouseover = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.cursor='hand';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf32205.img_63_onmouseover' }); }
};

/**
 * @method
 * @name btn_Cal14_onclick
 * @description btn_Cal14 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cal14_onclick = async function(e){
    try {
        await scwin.cal14()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf32205.btn_Cal14_onclick' }); }
};

/**
 * @method
 * @name btn_ExcelDown_onclick
 * @description btn_ExcelDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ExcelDown_onclick = async function(e){
    try {
        await scwin.excelDown('excelData14')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf32205.btn_ExcelDown_onclick' }); }
};

/**
 * @method
 * @name btn_Cal15_onclick
 * @description btn_Cal15 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cal15_onclick = async function(e){
    try {
        await scwin.cal15()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf32205.btn_Cal15_onclick' }); }
};

/**
 * @method
 * @name btn_ExcelDown_2_onclick
 * @description btn_ExcelDown_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ExcelDown_2_onclick = async function(e){
    try {
        await scwin.excelDown('excelData15')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf32205.btn_ExcelDown_2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Cal14
 * @description Cal14 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Cal14 = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal14"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal14", unresolved: "action:self_submit:tx_fn_Cal14" };
};

/**
 * @method
 * @name tx_fn_Cal15
 * @description Cal15 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Cal15 = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal15"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal15", unresolved: "action:self_submit:tx_fn_Cal15" };
};

/**
 * @method
 * @name tx_fn_ExcelDown
 * @description Excel Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ExcelDown = async function () {
    try { return await $c.data.downFile("/bizspt/excelDown.jsp", "", ($c.util.getComponent("dma_ExcelDownReq") ? $c.util.getComponent("dma_ExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name cal14
 * @description cal14 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal14 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : $c.util.getComponent('ipt_ISU_CD').focus());
        return;
    }
    if (($c.util.getComponent('cal_decisionDateForMnAPrice').getValue() == null ? '' : String($c.util.getComponent('cal_decisionDateForMnAPrice').getValue())) === '') {
        await $c.win.alert("[이사회결의일]을 입력하세요.");
        $c.util.getComponent("cal_decisionDateForMnAPrice").focus();
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_Cal14Req').set('method', "processCalculateRelatedDisclosure14");
    await scwin.tx_fn_Cal14();
};

/**
 * @method
 * @name cal15
 * @description cal15 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal15 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : $c.util.getComponent('ipt_ISU_CD').focus());
        return;
    }
    if (($c.util.getComponent('cal_decisionDateForStockBuyPrice').getValue() == null ? '' : String($c.util.getComponent('cal_decisionDateForStockBuyPrice').getValue())) === '') {
        await $c.win.alert("[이사회결의일]을 입력하세요.");
        $c.util.getComponent("cal_decisionDateForStockBuyPrice").focus();
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_Cal14Req').set('method', "processCalculateRelatedDisclosure15");
    await scwin.tx_fn_Cal15();
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @param {String} tableID tableID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function (tableID) {
    if (tableID.rows.length === 0) {
        await $c.win.alert("[계산하기]을 실행 후 다운로드 할 수 있습니다.");
        return;
    }
    $c.util.getComponent('dma_Cal14Req').set('excelData', tableID.outerHTML);
    scwin.form_frmISU_CD.method = "post";
    scwin.form_frmISU_CD.target = "_blank";
    await scwin.tx_fn_ExcelDown();
};
